def find_linear(pad):
 rows=[]
 for A,B in zip(demos_in,demos_out):
  for r in range(6):
   for c in range(5):
    vals=[]
    for dr,dc in offs9:
     rr,cc=r+dr,c+dc
     vals.append(A[rr][cc] if 0<=rr<6 and 0<=cc<5 else pad)
    rows.append((vals,B[r][c]))
 sols=[]
 for mask in range(1<<9):
  for const in (0,1):
   if all((const ^ sum(v for i,v in enumerate(vals) if mask>>i&1)%2)==y for vals,y in rows): sols.append((mask,const))
 return sols
